import re
with open('doc/Laboratory.md', 'r') as f:
    content = f.read()

# Extract all creatinine entries with patient IDs and values
lines = content.split('\n')
creatinine_entries = []
for line in lines:
    if 'creatinine' in line.lower():
        # Try to find patient ID (7+ digit number)
        patient_match = re.search(r'patient\s+(\d{6,})', line, re.IGNORECASE)
        # Look for creatinine value pattern like "creatinine was X mg/dL" or "creatinine of X mg/dL"
        value_match = re.search(r'creatinine\s+(?:was|of)?\s*([\d.]+)\s*mg/dl', line, re.IGNORECASE)
        if patient_match:
            pid = patient_match.group(1)
            val = None
            if value_match:
                val = float(value_match.group(1))
            creatinine_entries.append((pid, val))

print(f"Total entries: {len(creatinine_entries)}")

# Get unique patients with their creatinine values
patient_creatinine = {}
for pid, val in creatinine_entries:
    if val is not None:
        if pid not in patient_creatinine:
            patient_creatinine[pid] = []
        patient_creatinine[pid].append(val)

print(f"Unique patients with creatinine: {len(patient_creatinine)}")

# Show some examples
for pid, vals in list(patient_creatinine.items())[:10]:
    print(f"Patient {pid}: {vals}")

